using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OmensList", menuName = "Data/Battle/Omens System/Omen Data/Omens List")]
public class OmensList : ScriptableObject
{
	[Header("Character")]
	[SerializeField]
	private bool enableCharacter = true;

	[SerializeField]
	[ShowIf("enableCharacter")]
	private Character character;

	[Header("Omen Datas")]
	[SerializeField]
	private List<OmenData> omenDatas = new List<OmenData>();

	private Dictionary<string, string> blessingsChangedPostReleaseDictionary = new Dictionary<string, string>
	{
		{ "BehenianChakramOmenData", "BehenianHourglassOmenData" },
		{ "VacuumsWingsOmenData", "VacuumWingsOmenData" },
		{ "VacuumsWings", "VacuumWings" },
		{ "HeveliusAstrarium", "LacertianScepter" },
		{ "AustraAstrarium", "ApianLamp" },
		{ "SothisAstrarium", "BehenianHourglass" },
		{ "OrionAstrarium", "AquarianOrbs" },
		{ "IluminatingCompassOmenData", "IlluminatingCompassOmenData" },
		{ "TaintedKhepreshOmenData", "RegalKhepreshOmenData" },
		{ "ContemplationSarcophogusOmenData", "ContemplationSarcophagusOmenData" }
	};

	public Character Character => character;

	public List<OmenData> OmenDatas => omenDatas;

	public string GetBlessingNameFixedPostRelease(string omenName)
	{
		if (blessingsChangedPostReleaseDictionary.ContainsKey(omenName))
		{
			omenName = blessingsChangedPostReleaseDictionary[omenName];
		}
		return omenName;
	}

	public OmenData GetOmenData(string omenName)
	{
		omenName = GetBlessingNameFixedPostRelease(omenName);
		string omenNameFormatedToCompare = GetOmenNameFormatedToCompare(omenName);
		for (int i = 0; i < omenDatas.Count; i++)
		{
			if (omenNameFormatedToCompare == GetOmenNameFormatedToCompare(omenDatas[i].name))
			{
				return omenDatas[i];
			}
		}
		return null;
	}

	public string GetOmenNameFormatedToCompare(string omenName)
	{
		return omenName.Replace(" ", "").ToLower().Replace("omendata", "");
	}
}
